    private void order2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_order2ActionPerformed
String snacks = snackz.getText();
int snackQuantity = Integer.parseInt(snackquan.getText());
String drinks = drinkz.getText();
int drinkQuantity = Integer.parseInt(drinkquan.getText());

int snackprice = 0;
int drinkprice = 0;

if (snacks.equals("1")){
    snackprice = 20;

}
else if (snacks.equals("2")){
    snackprice = 25;
}

if (drinks.equals("1")){
    drinkprice = 20;
}
else if (drinks.equals("2")){
    drinkprice = 25;
}

int subtotal = (drinkprice * drinkQuantity)+ (snackprice * snackQuantity);
subtot.setText(String.valueOf(subtotal));




// TODO add your handling code here:
    }//GEN-LAST:event_order2ActionPerformed

    private void txtChangeActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_txtChangeActionPerformed
        double subtotal = Double.parseDouble(subtot.getText());
        double cash = Double.parseDouble(txtcash.getText());
        double change = cash - subtotal;
        
        txtchange.setText(String.valueOf(change));// TODO add your handling code here:
    }//GEN-LAST:event_txtChangeActionPerformed

